<?php

declare(strict_types=1);

namespace Vittix\Panchang\Tests\Accuracy;

use RuntimeException;

/**
 * Loads and validates the Swiss Ephemeris reference fixtures generated by
 * tools/reference/generate_fixtures.py.
 *
 * @phpstan-type Metadata array<string, mixed>
 * @phpstan-type Sample array<string, mixed>
 */
final class FixtureRepository
{
    private const FIXTURES = [
        'body_longitudes' => 'body_longitudes.json',
        'transitions' => 'transitions.json',
        'sun_moon_events' => 'sun_moon_events.json',
    ];

    public function __construct(
        private readonly string $baseDir,
    ) {
    }

    /**
     * Repository pointing at tests/fixtures/reference/ next to this file's package.
     */
    public static function default(): self
    {
        return new self(dirname(__DIR__) . DIRECTORY_SEPARATOR . 'fixtures' . DIRECTORY_SEPARATOR . 'reference');
    }

    public function path(string $dataset): string
    {
        if (!isset(self::FIXTURES[$dataset])) {
            throw new RuntimeException("Unknown fixture dataset '{$dataset}'.");
        }

        return $this->baseDir . DIRECTORY_SEPARATOR . self::FIXTURES[$dataset];
    }

    public function has(string $dataset): bool
    {
        return is_file($this->path($dataset));
    }

    /**
     * @return Metadata
     */
    public function metadata(string $dataset): array
    {
        return self::arrayField($this->load($dataset), 'metadata');
    }

    /**
     * @return list<Sample>
     */
    public function samples(string $dataset): array
    {
        $data = $this->load($dataset);
        $samples = $data['samples'] ?? null;

        if (!is_array($samples)) {
            throw new RuntimeException("Fixture '{$dataset}' has no samples array.");
        }

        $out = [];
        foreach ($samples as $sample) {
            if (!is_array($sample)) {
                throw new RuntimeException("Fixture '{$dataset}' contains a non-object sample.");
            }
            /** @var Sample $sample */
            $out[] = $sample;
        }

        return $out;
    }

    /**
     * @return array<string, mixed>
     */
    private function load(string $dataset): array
    {
        $path = $this->path($dataset);

        if (!is_file($path)) {
            throw new RuntimeException(
                "Reference fixture '{$path}' not found. Regenerate with:\n"
                . "    pip install -r tools/reference/requirements-dev.txt\n"
                . '    python tools/reference/generate_fixtures.py'
            );
        }

        $raw = file_get_contents($path);
        if ($raw === false) {
            throw new RuntimeException("Could not read fixture '{$path}'.");
        }

        $decoded = json_decode($raw, true);
        if (!is_array($decoded)) {
            throw new RuntimeException("Fixture '{$path}' is not valid JSON.");
        }

        /** @var array<string, mixed> $decoded */
        return $decoded;
    }

    // ---------------------------------------------------------------------
    // Typed field accessors (keep PHPStan level 8 happy without casting noise)
    // ---------------------------------------------------------------------

    /**
     * @param array<string, mixed> $data
     */
    public static function stringField(array $data, string $key): string
    {
        $value = $data[$key] ?? null;
        if (!is_string($value)) {
            throw new RuntimeException("Fixture field '{$key}' missing or not a string.");
        }

        return $value;
    }

    /**
     * @param array<string, mixed> $data
     */
    public static function floatField(array $data, string $key): float
    {
        $value = $data[$key] ?? null;
        if (!is_float($value) && !is_int($value)) {
            throw new RuntimeException("Fixture field '{$key}' missing or not numeric.");
        }

        return (float) $value;
    }

    /**
     * @param array<string, mixed> $data
     */
    public static function intField(array $data, string $key): int
    {
        $value = $data[$key] ?? null;
        if (!is_int($value)) {
            throw new RuntimeException("Fixture field '{$key}' missing or not an integer.");
        }

        return $value;
    }

    /**
     * @param array<string, mixed> $data
     * @return array<string, mixed>
     */
    public static function arrayField(array $data, string $key): array
    {
        $value = $data[$key] ?? null;
        if (!is_array($value)) {
            throw new RuntimeException("Fixture field '{$key}' missing or not an object.");
        }

        /** @var array<string, mixed> $value */
        return $value;
    }
}
